def solution(n, k, enemy):
    left, right = 0, len(enemy)

    while left < right:
        mid = (left + right + 1) // 2
        total_damage = sum(sorted(enemy[:mid])[:k]) + sum(enemy[:mid]) - sum(sorted(enemy[:mid])[:k])

        if total_damage <= n:
            left = mid
        else:
            right = mid - 1

    return left

def solution(expression):
    import re
    from itertools import permutations

    numbers = list(map(int, re.findall(r'\d+', expression)))
    operators = re.findall(r'[+\-*]', expression)
    max_result = 0

    for perm in permutations(set(operators)):
        exp = expression
        for op in perm:
            while op in exp:
                parts = re.split(r'(\D)', exp)
                new_parts = []
                i = 0
                while i < len(parts):
                    if parts[i] == op:
                        left = int(new_parts.pop()) if new_parts else int(parts[i-1])
                        right = int(parts[i+1])
                        if op == '+':
                            new_parts.append(str(left + right))
                        elif op == '-':
                            new_parts.append(str(left - right))
                        elif op == '*':
                            new_parts.append(str(left * right))
                        i += 2
                    else:
                        new_parts.append(parts[i])
                        i += 1
                exp = ''.join(new_parts)

        max_result = max(max_result, abs(int(exp)))

    return max_result

def solution(signals):
    def get_cycle_time(signal):
        return sum(signal)

    def is_yellow(time, signal):
        cycle_time = get_cycle_time(signal)
        time_in_cycle = time % cycle_time
        green_time = signal[0]
        yellow_time = signal[0] + signal[1]
        return green_time <= time_in_cycle < yellow_time

    max_time = 1
    for signal in signals:
        max_time = max(max_time, get_cycle_time(signal))

    for time in range(1, max_time * 100):  # Arbitrary large multiplier to ensure we find a solution if it exists
        if all(is_yellow(time, signal) for signal in signals):
            return time

    return -1

