def solution(book_time):
    time_slots = []
    for start, end in book_time:
        start_hour, start_minute = map(int, start.split(':'))
        end_hour, end_minute = map(int, end.split(':'))
        end_clean_hour = end_hour
        end_clean_minute = end_minute + 10
        if end_clean_minute >= 60:
            end_clean_hour += 1
            end_clean_minute -= 60
        time_slots.append((start_hour * 60 + start_minute, end_clean_hour * 60 + end_clean_minute))

    time_slots.sort()

    import heapq
    heap = []

    for start, end in time_slots:
        if heap and heap[0] <= start:
            heapq.heappop(heap)
        heapq.heappush(heap, end)

    return len(heap)

def solution(numbers, target):
