def solution(cap, n, deliveries, pickups):
    total_distance = 0
    delivery_index = n - 1
    pickup_index = n - 1

    while delivery_index >= 0 or pickup_index >= 0:
        while delivery_index >= 0 and deliveries[delivery_index] == 0:
            delivery_index -= 1
        while pickup_index >= 0 and pickups[pickup_index] == 0:
            pickup_index -= 1

        if delivery_index >= 0:
            total_distance += (delivery_index + 1) * 2
            load = 0
            while delivery_index >= 0 and load < cap:
                load += deliveries[delivery_index]
                deliveries[delivery_index] = 0
                delivery_index -= 1

        if pickup_index >= 0:
            total_distance += (pickup_index + 1) * 2
            load = 0
            while pickup_index >= 0 and load < cap:
                load += pickups[pickup_index]
                pickups[pickup_index] = 0
                pickup_index -= 1

    return total_distance

def solution(number, limit, power):
