def solution(plans):
    from collections import deque

    def time_to_minutes(t):
        h, m = map(int, t.split(':'))
        return h * 60 + m

    plans = sorted([(name, time_to_minutes(start), int(playtime)) for name, start, playtime in plans], key=lambda x: x[1])
    result = []
    ongoing = None
    paused = deque()

    for name, start, playtime in plans:
        if ongoing:
            if ongoing[1] > start:
                paused.append(ongoing)
                ongoing = (ongoing[0], ongoing[1] + ongoing[2] - (start - ongoing[1]), ongoing[2])
            else:
                ongoing = (ongoing[0], ongoing[1] + ongoing[2], ongoing[2])

        if ongoing:
            ongoing = (ongoing[0], ongoing[1] - (start - ongoing[1]), ongoing[2])

        if ongoing and ongoing[1] <= 0:
            result.append(ongoing[0])
            ongoing = None

        ongoing = (name, start + playtime, playtime)

    if ongoing:
        result.append(ongoing[0])

    while paused:
        ongoing = paused.pop()
        result.append(ongoing[0])

    return result

def solution(video_len, pos, op_start, op_end, commands):
    def time_to_seconds(t):
        mm, ss = map(int, t.split(':'))
        return mm * 60 + ss

    def seconds_to_time(s):
        mm, ss = divmod(s, 60)
        return f"{mm:02}:{ss:02}"

    video_length = time_to_seconds(video_len)
    current_position = time_to_seconds(pos)

    op_start_sec = time_to_seconds(op_start)
    op_end_sec = time_to_seconds(op_end)

    for command in commands:
        if command == "prev":
            current_position = max(0, current_position - 10)
        elif command == "next":
            current_position = min(video_length, current_position + 10)

        if op_start_sec <= current_position <= op_end_sec:
            current_position = op_end_sec

    return seconds_to_time(current_position)

