def solution(n, info):
    from itertools import combinations_with_replacement

    max_diff = -1
    best_case = [-1]

    for arrows in combinations_with_replacement(range(11), n):
        score_ryan = [0] * 11
        for score in arrows:
            score_ryan[10 - score] += 1

        score_apich = sum((10 - i) * info[i] for i in range(11))
        score_ryan_total = sum((10 - i) * score_ryan[i] for i in range(11))

        for i in range(11):
            if score_ryan[i] > info[i]:
                score_ryan_total += (10 - i)
                score_apich -= (10 - i)

        if score_ryan_total > score_apich:
            diff = score_ryan_total - score_apich
            if diff > max_diff:
                max_diff = diff
                best_case = score_ryan
            elif diff == max_diff:
                for i in range(11):
                    if score_ryan[i] > best_case[i]:
                        best_case = score_ryan
                        break
                    elif score_ryan[i] < best_case[i]:
                        break

    return best_case if max_diff > 0 else [-1]

