def solution(land):
    n = len(land)
    m = len(land[0])
    visited = [[False] * m for _ in range(n)]

    def dfs(x, y):
        stack = [(x, y)]
        size = 0
        while stack:
            cx, cy = stack.pop()
            if visited[cx][cy]:
                continue
            visited[cx][cy] = True
            size += 1
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = cx + dx, cy + dy
                if 0 <= nx < n and 0 <= ny < m and land[nx][ny] == 1 and not visited[nx][ny]:
                    stack.append((nx, ny))
        return size

    oil_sizes = []

    for i in range(n):
        for j in range(m):
            if land[i][j] == 1 and not visited[i][j]:
                oil_sizes.append(dfs(i, j))

    max_oil = 0
    for j in range(m):
        total_oil = 0
        for i in range(n):
            if land[i][j] == 1:
                total_oil += oil_sizes.pop(0)
        max_oil = max(max_oil, total_oil)

    return max_oil

