def solution(friends, gifts):
    gift_count = {friend: [0, 0] for friend in friends}

    for gift in gifts:
        giver, receiver = gift.split()
        gift_count[giver][0] += 1
        gift_count[receiver][1] += 1

    gift_index = {friend: gift_count[friend][0] - gift_count[friend][1] for friend in friends}
    received_gifts = {friend: 0 for friend in friends}

    for i in range(len(friends)):
        for j in range(len(friends)):
            if i != j:
                giver = friends[i]
                receiver = friends[j]
                if gift_count[giver][0] > gift_count[receiver][0]:
                    received_gifts[receiver] += 1
                elif gift_count[giver][0] < gift_count[receiver][0]:
                    received_gifts[giver] += 1
                else:
                    if gift_index[giver] > gift_index[receiver]:
                        received_gifts[receiver] += 1
                    elif gift_index[giver] < gift_index[receiver]:
                        received_gifts[giver] += 1

    return max(received_gifts.values())

