def solution(maps):
    from collections import deque

    def bfs(start, target):
        queue = deque([start])
        visited = [[False] * len(maps[0]) for _ in range(len(maps))]
        visited[start[0]][start[1]] = True
        distance = 0

        while queue:
            for _ in range(len(queue)):
                x, y = queue.popleft()
                if (x, y) == target:
                    return distance
                for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < len(maps) and 0 <= ny < len(maps[0]) and not visited[nx][ny] and maps[nx][ny] != 'X':
                        visited[nx][ny] = True
                        queue.append((nx, ny))
            distance += 1
        return -1

    start = end = lever = None
    for i in range(len(maps)):
        for j in range(len(maps[0])):
            if maps[i][j] == 'S':
                start = (i, j)
            elif maps[i][j] == 'E':
                end = (i, j)
            elif maps[i][j] == 'L':
                lever = (i, j)

    to_lever = bfs(start, lever)
    if to_lever == -1:
        return -1
    to_exit = bfs(lever, end)
    if to_exit == -1:
        return -1
    return to_lever + to_exit

def solution(m, n, picture):
    def dfs(x, y, color):
        if x < 0 or x >= m or y < 0 or y >= n or picture[x][y] != color:
            return 0
        picture[x][y] = 0
        area = 1
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            area += dfs(x + dx, y + dy, color)
        return area

    num_areas = 0
    max_area = 0

    for i in range(m):
        for j in range(n):
            if picture[i][j] != 0:
                num_areas += 1
                max_area = max(max_area, dfs(i, j, picture[i][j]))

    return [num_areas, max_area]

def solution(n):
    def backtrack(row, cols, diag1, diag2):
        if row == n:
            return 1
        count = 0
        for col in range(n):
            if col in cols or (row + col) in diag1 or (row - col) in diag2:
                continue
            cols.add(col)
            diag1.add(row + col)
            diag2.add(row - col)
            count += backtrack(row + 1, cols, diag1, diag2)
            cols.remove(col)
            diag1.remove(row + col)
            diag2.remove(row - col)
        return count

    return backtrack(0, set(), set(), set())

