def solution(cost, hint):
    n = len(cost)
    dp = [[float('inf')] * n for _ in range(1 << n)]
    dp[0][0] = 0

    for mask in range(1 << n):
        for stage in range(n):
            if mask & (1 << stage):
                continue
            for used in range(n):
                if used > stage:
                    continue
                current_cost = dp[mask][used] + cost[stage][used]
                if current_cost < dp[mask | (1 << stage)][stage + 1]:
                    dp[mask | (1 << stage)][stage + 1] = current_cost

            if stage < n - 1:
                for price, *hints in hint[stage]:
                    new_mask = mask
                    for h in hints:
                        new_mask |= (1 << (h - 1))
                    current_cost = dp[mask][used] + price
                    if current_cost < dp[new_mask][used + len(hints)]:
                        dp[new_mask][used + len(hints)] = current_cost

    return min(dp[(1 << n) - 1])

