    visited = set()
    cycle_lengths = []

    def dfs(x, y, dir_idx):
        path = []
        start = (x, y, dir_idx)
        while True:
            if (x, y, dir_idx) in visited:
                return 0
            visited.add((x, y, dir_idx))
            path.append((x, y))
            if grid[x][y] == 'S':
                x, y = (x + directions[dir_idx][0]) % len(grid), (y + directions[dir_idx][1]) % len(grid[0])
            elif grid[x][y] == 'L':
                dir_idx = (dir_idx - 1) % 4
                x, y = (x + directions[dir_idx][0]) % len(grid), (y + directions[dir_idx][1]) % len(grid[0])
            else:  # grid[x][y] == 'R'
                dir_idx = (dir_idx + 1) % 4
                x, y = (x + directions[dir_idx][0]) % len(grid), (y + directions[dir_idx][1]) % len(grid[0])
            if (x, y, dir_idx) == start:
                cycle_lengths.append(len(path))
                return len(path)

    for i in range(len(grid)):
        for j in range(len(grid[0])):
            for d in range(4):
                if (i, j, d) not in visited:
                    dfs(i, j, d)

    return sorted(cycle_lengths)

