    def move(start, end):
        path = []
        r1, c1 = points[start - 1]
        r2, c2 = points[end - 1]
        while (r1, c1) != (r2, c2):
            if r1 < r2:
                r1 += 1
            elif r1 > r2:
                r1 -= 1
            elif c1 < c2:
                c1 += 1
            else:
                c1 -= 1
            path.append((r1, c1))
        return path

