        if n == 0:
            return 1 if l <= 1 <= r else 0
        length = 5 ** n
        mid_start = (length // 3) + 1
        mid_end = (2 * length // 3)

        if r < 1 or l > length:
            return 0
        if l <= mid_start and r >= mid_end:
