    from collections import defaultdict
    import math

    def time_to_minutes(time):
        h, m = map(int, time.split(':'))
        return h * 60 + m

    car_times = defaultdict(int)
    in_cars = {}

    for record in records:
        time, car_number, status = record.split()
        minutes = time_to_minutes(time)

        if status == "IN":
            in_cars[car_number] = minutes
        else:
            car_times[car_number] += minutes - in_cars.pop(car_number)

    for car_number, minutes in in_cars.items():
        car_times[car_number] += time_to_minutes("23:59") - minutes

    result = []
    for car_number in sorted(car_times.keys()):
        total_time = car_times[car_number]
        if total_time <= fees[0]:
            result.append(fees[1])
        else:
            extra_time = total_time - fees[0]
            extra_fee = math.ceil(extra_time / fees[2]) * fees[3]
            result.append(fees[1] + extra_fee)

    return result

