def solution(n, data):
    friends = ['A', 'C', 'F', 'J', 'M', 'N', 'R', 'T']
    conditions = []

    for condition in data:
        a, _, b, op, d = condition
        conditions.append((a, b, op, int(d) + 1))

    def check(perm):
        for a, b, op, d in conditions:
            idx_a = perm.index(a)
            idx_b = perm.index(b)
            distance = abs(idx_a - idx_b) - 1

            if op == '=' and distance != d:
                return False
            elif op == '<' and distance >= d:
                return False
            elif op == '>' and distance <= d:
                return False
        return True

    return sum(1 for perm in permutations(friends) if check(perm))

