def solution(arr):
    def compress(x, y, n):
        if n == 1:
            return [1, 0] if arr[x][y] == 1 else [0, 1]

        half = n // 2
        top_left = compress(x, y, half)
        top_right = compress(x, y + half, half)
        bottom_left = compress(x + half, y, half)
        bottom_right = compress(x + half, y + half, half)

        total_ones = top_left[0] + top_right[0] + bottom_left[0] + bottom_right[0]
        total_zeros = top_left[1] + top_right[1] + bottom_left[1] + bottom_right[1]

        if total_ones == 0:
            return [0, 1]
        elif total_zeros == 0:
            return [1, 0]
        else:
            return [total_ones, total_zeros]

    return compress(0, 0, len(arr))

