def solution(n, k):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    def to_k_base(num, base):
        if num == 0:
            return '0'
        digits = []
        while num:
            digits.append(str(num % base))
            num //= base
        return ''.join(digits[::-1])

    k_base = to_k_base(n, k)
    candidates = k_base.split('0')
    count = 0

    for candidate in candidates:
        if candidate and is_prime(int(candidate)):
            count += 1

    return count

