def solution(p):
    if not p:
        return ""

    def is_correct(u):
        balance = 0
        for char in u:
            if char == '(':
                balance += 1
            else:
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    def divide(p):
        balance = 0
        for i in range(len(p)):
            if p[i] == '(':
                balance += 1
            else:
                balance -= 1
            if balance == 0:
                return p[:i + 1], p[i + 1:]

    u, v = divide(p)

    if is_correct(u):
        return u + solution(v)
    else:
        new_v = "(" + solution(v) + ")"
        u = u[1:-1]
        u = ''.join(')' if char == '(' else '(' for char in u)
        return new_v + u

