def solution(n, infection, edges, k):
    from collections import defaultdict, deque

    graph = defaultdict(list)
    for x, y, t in edges:
        graph[x].append((y, t))
        graph[y].append((x, t))

    def bfs(start, types):
        visited = set()
        queue = deque([start])
        visited.add(start)
        infected_count = 1

        while queue:
            node = queue.popleft()
            for neighbor, t in graph[node]:
                if neighbor not in visited and t in types:
                    visited.add(neighbor)
                    queue.append(neighbor)
                    infected_count += 1
        return infected_count

    max_infected = 1
    for i in range(1, 4):
        if k > 0:
            infected = bfs(infection, [i])
            max_infected = max(max_infected, infected)
            for j in range(1, 4):
                if j != i and k > 1:
                    infected = bfs(infection, [i, j])
                    max_infected = max(max_infected, infected)

    return max_infected

