def solution(diffs, times, limit):
    def can_complete(level):
        total_time = 0
        prev_time = 0

        for i in range(len(diffs)):
            if diffs[i] <= level:
                total_time += times[i]
            else:
                mistakes = diffs[i] - level
                total_time += (mistakes * (times[i] + prev_time)) + times[i]
            prev_time = times[i]

        return total_time <= limit

    left, right = 1, max(diffs)

    while left < right:
        mid = (left + right) // 2
        if can_complete(mid):
            right = mid
        else:
            left = mid + 1

    return left

