def solution(info, query):
    from itertools import combinations
    from collections import defaultdict
    import bisect

    info_dict = defaultdict(list)

    for i in info:
        lang, job, career, food, score = i.split()
        score = int(score)
        info_dict[(lang, job, career, food)].append(score)
        for j in range(5):
            for comb in combinations([lang, job, career, food], j):
                info_dict[tuple(comb)].append(score)

    for key in info_dict.keys():
        info_dict[key].sort()

    answer = []
    for q in query:
        q = q.replace(" and ", " ").split()
        score = int(q[-1])
        key = tuple(q[:-1])
        if key in info_dict:
            count = len(info_dict[key]) - bisect.bisect_left(info_dict[key], score)
            answer.append(count)
        else:
            answer.append(0)

    return answer
